import binascii
for checksum, width in ((binascii.crc32, 32), (binascii.crc_hqx, 16)):
    assert checksum.__module__ == 'binascii'
    assert checksum.__text_signature__ == ('($module, data, crc=0, /)' if width == 32 else '($module, data, crc, /)')
    for seed in (0, 1, -1, -(1 << 100), (1 << 100) + 7):
        assert checksum(b'', seed) == seed & ((1 << width) - 1)
        assert type(checksum(b'', seed)) is int
    events = []
    class Seed:
        def __index__(self):
            events.append('index')
            return -1
    assert checksum(b'abc', Seed()) == checksum(b'abc', -1)
    assert events == ['index']
    data = bytearray(range(256))
    view = memoryview(data)
    expected = checksum(bytes(data), 0)
    assert checksum(view, 0) == expected
    for split in range(len(data) + 1):
        assert checksum(view[split:], checksum(view[:split], 0)) == expected
    try:
        checksum(view[::2], 0)
    except BufferError:
        pass
    else:
        assert False
    view.release()
    try:
        checksum(view, 0)
    except ValueError:
        pass
    else:
        assert False
    data.extend(b'Z')
    failure = ValueError('seed failed')
    class Failure:
        def __index__(self):
            raise failure
    try:
        checksum(data, Failure())
    except ValueError as caught:
        assert caught is failure and caught.__traceback__ is not None
    else:
        assert False
    data.extend(b'Z')
assert binascii.crc32(b'123456789') == 0xcbf43926
assert binascii.crc_hqx(b'123456789', 0) == 0x31c3
